stories:{
photoshoot:{
category:"ФОТОГРАФІЯ",
title:"Як підготувати улюбленця до журнальної фотосесії",
intro:"Грумінг, світло, комфорт і проста підготовка допомагають створити справжній редакційний портрет.",
author:"Редакція PETS & DOGUE",date:"13 серпня 2026",readingTime:"5 хв читання",
body:[
{type:"text",text:"Успішна фотосесія починається задовго до першого кадру. Мета — не змусити тварину позувати, а створити умови, у яких природно проявляться її характер і краса."},
{type:"heading",text:"Підготовка без зайвої стилізації"},
{type:"text",text:"Грумінг має підкреслювати улюбленця, а не маскувати його. Чисті очі, доглянута шерсть і правильно підібраний аксесуар зазвичай працюють найкраще."},
{type:"heading",text:"Світло змінює все"},
{type:"text",text:"М’яке природне світло комфортніше для тварини та красивіше виглядає в кадрі."},
{type:"quote",text:"Найсильніший портрет часто з’являється тоді, коли улюбленець перестає позувати й просто залишається собою."},
{type:"heading",text:"Комфорт понад усе"},
{type:"text",text:"Візьміть воду, ласощі, знайомий плед і робіть перерви. Не жертвуйте добробутом тварини заради фотографії."}
]
},
travel:{
category:"ПОДОРОЖІ",
title:"Розквіт розкішних подорожей з улюбленцями",
intro:"Готелі, вілли та напрямки перебудовують преміальний туризм для гостей, які подорожують разом із тваринами.",
author:"Редакція PETS & DOGUE",date:"13 серпня 2026",readingTime:"5 хв читання",
body:[
{type:"text",text:"Світ розкішних подорожей змінюється. Для дедалі більшої кількості людей справжня гостинність включає й тварину, яка є частиною сім’ї."},
{type:"heading",text:"Більше, ніж просто дозволити тварин"},
{type:"text",text:"Найкращі pet-friendly готелі продумують номер, вихід на вулицю, харчування, маршрути прогулянок і підготовку персоналу."},
{type:"heading",text:"Новий стандарт гостинності"},
{type:"text",text:"Справжня розкіш — це зрозумілі правила, безпечний простір і сервіс, який полегшує подорож."},
{type:"quote",text:"Pet-friendly luxury працює найкраще, коли тварину сприймають як гостя, а не як виняток."},
{type:"heading",text:"Подорож із думкою про улюбленця"},
{type:"text",text:"Красивий напрямок має сенс лише тоді, коли подорож відповідає здоров’ю, темпераменту та звичному ритму тварини."}
]
},
places:{
category:"КОРИСНИЙ ГІД",
title:"Як DOGUE Trust захищає рекомендації pet-friendly місць",
intro:"Відгуки спільноти та перевірка допомагають зберігати інформацію корисною, актуальною й надійною.",
author:"Редакція PETS & DOGUE",date:"13 серпня 2026",readingTime:"4 хв читання",
body:[
{type:"text",text:"Заклад може називати себе pet-friendly і водночас давати поганий досвід. Правила та персонал змінюються, а інформація застаріває."},
{type:"heading",text:"Перевірка спільнотою важлива"},
{type:"text",text:"Відвідувачі можуть повідомляти про змінені правила, неправильний графік, обмежені зони або місця, які більше не приймають тварин."},
{type:"heading",text:"DOGUE Trust"},
{type:"text",text:"DOGUE Trust задуманий як додатковий рівень довіри до рекомендацій спільноти."},
{type:"quote",text:"Довіра зростає, коли неправильну інформацію можна виправити."},
{type:"heading",text:"Живий гід"},
{type:"text",text:"Мета — створити не статичний каталог, а міжнародний гід, що постійно оновлюється на основі реального досвіду."}
]
},
volunteers:{
category:"СПІЛЬНОТА",
title:"Люди, які допомагають тваринам за лаштунками",
intro:"Транспорт, перетримка, фотографії, збір коштів і маленькі практичні дії можуть повністю змінити шанси тварини.",
author:"Редакція PETS & DOGUE",date:"13 серпня 2026",readingTime:"5 хв читання",
body:[
{type:"text",text:"Порятунок тварин рідко є роботою однієї людини. За кожною історією можуть стояти водії, перетримки, фотографи, волонтери та люди, які поширюють інформацію."},
{type:"heading",text:"Малі завдання дають великий результат"},
{type:"text",text:"Одна людина відвозить тварину до ветеринара, інша робить фотографії, ще хтось допомагає кормом або перекладом."},
{type:"heading",text:"Видимість може рятувати життя"},
{type:"text",text:"Хороші фотографії та точні історії допомагають потрібній людині помітити тварину."},
{type:"quote",text:"Допомога не завжди потребує великого жесту. Надійність часто цінніша."},
{type:"heading",text:"Сильна спільнота"},
{type:"text",text:"Коли люди допомагають своїми навичками й часом, організації отримують надійну мережу підтримки навколо тварин."}
]
}
}
