stories:{
photoshoot:{
category:"PHOTOGRAPHIE",title:"Comment préparer votre animal pour une séance photo de magazine",
intro:"Toilettage, lumière, confort et préparation simple peuvent transformer un portrait en image éditoriale.",
author:"Par la rédaction PETS & DOGUE",date:"13 août 2026",readingTime:"5 min de lecture",
body:[
{type:"text",text:"Une séance réussie commence bien avant la première photo. L’objectif n’est pas d’imposer une pose parfaite, mais de créer un environnement où la personnalité de l’animal apparaît naturellement."},
{type:"heading",text:"Préparer sans surcharger"},
{type:"text",text:"Le toilettage doit mettre l’animal en valeur sans le déguiser. Un pelage propre et un accessoire bien choisi suffisent souvent."},
{type:"heading",text:"La lumière change tout"},
{type:"text",text:"Une lumière naturelle douce est flatteuse et plus confortable pour l’animal."},
{type:"quote",text:"Le portrait le plus fort apparaît souvent lorsque l’animal cesse de poser et redevient simplement lui-même."},
{type:"heading",text:"Le confort avant tout"},
{type:"text",text:"Prévoyez de l’eau, des friandises et des pauses. Le bien-être de l’animal passe toujours avant la photo."}
]
},
travel:{
category:"VOYAGE",title:"L’essor du voyage de luxe avec les animaux",
intro:"Hôtels, villas et destinations réinventent le voyage premium pour les clients qui voyagent avec leurs animaux.",
author:"Par la rédaction PETS & DOGUE",date:"13 août 2026",readingTime:"5 min de lecture",
body:[
{type:"text",text:"Le voyage de luxe évolue. Pour de nombreux voyageurs, l’hospitalité véritable inclut désormais l’animal qui partage leur vie."},
{type:"heading",text:"Plus que simplement accepter les animaux"},
{type:"text",text:"Les meilleurs hôtels pensent à l’accès extérieur, aux repas, aux promenades et à un personnel préparé."},
{type:"heading",text:"Un meilleur standard d’hospitalité"},
{type:"text",text:"Le vrai luxe réside dans des règles claires, des espaces sûrs et un service qui simplifie le séjour."},
{type:"quote",text:"Le luxe pet-friendly fonctionne lorsque l’animal est considéré comme un invité, et non comme une exception."},
{type:"heading",text:"Voyager en pensant à l’animal"},
{type:"text",text:"La destination doit respecter sa santé, son tempérament et sa routine."}
]
},
places:{
category:"GUIDE PRATIQUE",title:"Comment DOGUE Trust protège les recommandations pet-friendly",
intro:"Les signalements de la communauté et la vérification permettent de garder les informations utiles et fiables.",
author:"Par la rédaction PETS & DOGUE",date:"13 août 2026",readingTime:"4 min de lecture",
body:[
{type:"text",text:"Un lieu peut se dire pet-friendly tout en offrant une mauvaise expérience. Les règles changent et les informations deviennent obsolètes."},
{type:"heading",text:"La vérification communautaire compte"},
{type:"text",text:"Les visiteurs peuvent signaler les horaires incorrects, les politiques modifiées ou les zones désormais interdites aux animaux."},
{type:"heading",text:"DOGUE Trust"},
{type:"text",text:"DOGUE Trust apporte une couche supplémentaire de confiance autour des recommandations de la communauté."},
{type:"quote",text:"La confiance grandit lorsque les informations erronées peuvent être corrigées."},
{type:"heading",text:"Un guide vivant"},
{type:"text",text:"L’objectif est de créer un guide international évolutif fondé sur des expériences réelles."}
]
},
volunteers:{
category:"COMMUNAUTÉ",title:"Les personnes qui aident les animaux en coulisses",
intro:"Transport, familles d’accueil, photographie et petites actions pratiques peuvent complètement changer les chances d’un animal.",
author:"Par la rédaction PETS & DOGUE",date:"13 août 2026",readingTime:"5 min de lecture",
body:[
{type:"text",text:"Le sauvetage animal est rarement le travail d’une seule personne. Derrière une adoption se trouvent souvent chauffeurs, familles d’accueil, photographes et bénévoles."},
{type:"heading",text:"Les petites tâches créent de grands résultats"},
{type:"text",text:"Une personne conduit l’animal chez le vétérinaire, une autre réalise des photos, une autre encore aide avec la nourriture."},
{type:"heading",text:"La visibilité peut sauver des vies"},
{type:"text",text:"De bonnes photos et des histoires exactes peuvent aider la bonne personne à remarquer un animal."},
{type:"quote",text:"Aider ne demande pas toujours un grand geste. La fiabilité a souvent plus de valeur."},
{type:"heading",text:"Une communauté plus forte"},
{type:"text",text:"Lorsque chacun aide selon ses compétences et son temps, les associations gagnent un réseau fiable."}
]
}
}
