stories:{
photoshoot:{category:"FOTOGRAFERING",title:"Slik forbereder du kjæledyret ditt til en magasinshoot",intro:"Stell, lys og komfort kan skape et ekte redaksjonelt portrett.",author:"Av PETS & DOGUE Editorial",date:"13. august 2026",readingTime:"5 min lesing",body:[{type:"text",text:"En god fotografering starter før det første bildet. Målet er å skape forhold der dyrets personlighet vises naturlig."},{type:"heading",text:"Forbered uten overstyling"},{type:"text",text:"Stell skal fremheve dyret, ikke skjule det."},{type:"heading",text:"Lys forandrer alt"},{type:"text",text:"Mykt naturlig lys er behagelig og flatterende."},{type:"quote",text:"Det sterkeste portrettet kommer ofte når dyret slutter å posere og bare er seg selv."},{type:"heading",text:"Komfort først"},{type:"text",text:"Vann, godbiter og pauser er viktige. Trivsel kommer alltid foran bildet."}]},
travel:{category:"REISER",title:"Veksten i luksusreiser med kjæledyr",intro:"Hoteller og reisemål endrer premiumreiser for gjester som reiser med dyr.",author:"Av PETS & DOGUE Editorial",date:"13. august 2026",readingTime:"5 min lesing",body:[{type:"text",text:"Luksusreiser endrer seg. For flere mennesker inkluderer ekte gjestfrihet også dyret."},{type:"heading",text:"Mer enn bare å tillate dyr"},{type:"text",text:"De beste hotellene tenker på plass, uteområder, mat og turmuligheter."},{type:"heading",text:"En bedre standard"},{type:"text",text:"Ekte luksus betyr tydelige regler, trygge områder og tjenester som gjør reisen enklere."},{type:"quote",text:"Kjæledyrvennlig luksus fungerer når dyret behandles som en gjest."},{type:"heading",text:"Reis med dyret i tankene"},{type:"text",text:"Reisen må passe dyrets helse, temperament og rutine."}]},
places:{category:"NYTTIG GUIDE",title:"Slik beskytter DOGUE Trust kjæledyrvennlige anbefalinger",intro:"Rapporter og verifisering bidrar til å holde informasjon pålitelig.",author:"Av PETS & DOGUE Editorial",date:"13. august 2026",readingTime:"4 min lesing",body:[{type:"text",text:"Et sted kan kalle seg kjæledyrvennlig og likevel gi en dårlig opplevelse. Regler endres og informasjon blir gammel."},{type:"heading",text:"Verifisering fra fellesskapet betyr noe"},{type:"text",text:"Besøkende kan rapportere endrede regler, tider og begrensninger."},{type:"heading",text:"DOGUE Trust"},{type:"text",text:"DOGUE Trust legger et ekstra lag med tillit rundt anbefalingene."},{type:"quote",text:"Tillit vokser når feil informasjon kan rettes."},{type:"heading",text:"En levende guide"},{type:"text",text:"Målet er en internasjonal guide som oppdateres gjennom virkelige erfaringer."}]},
volunteers:{category:"FELLESSKAP",title:"Menneskene som hjelper dyr bak kulissene",intro:"Transport, fosterhjem, fotografering og små handlinger kan endre et dyrs muligheter.",author:"Av PETS & DOGUE Editorial",date:"13. august 2026",readingTime:"5 min lesing",body:[{type:"text",text:"Dyre-redning er sjelden arbeidet til én person. Bak en adopsjon står ofte sjåfører, fosterhjem, fotografer og frivillige."},{type:"heading",text:"Små oppgaver, store resultater"},{type:"text",text:"Én kjører til veterinæren, en annen fotograferer, og en tredje hjelper med mat."},{type:"heading",text:"Synlighet kan redde liv"},{type:"text",text:"Gode bilder og korrekte historier hjelper riktig person med å oppdage dyret."},{type:"quote",text:"Hjelp trenger ikke alltid være en stor gest. Pålitelighet er ofte mer verdifullt."},{type:"heading",text:"Et sterkere fellesskap"},{type:"text",text:"Når folk bidrar med ferdighetene sine, skapes et pålitelig støttenettverk."}]}
}
