stories:{
photoshoot:{category:"التصوير",title:"كيف تجهّز حيوانك الأليف لجلسة تصوير لمجلة",intro:"العناية والإضاءة والراحة يمكن أن تحول الصورة إلى بورتريه تحريري احترافي.",author:"هيئة تحرير PETS & DOGUE",date:"13 أغسطس 2026",readingTime:"5 دقائق للقراءة",body:[{type:"text",text:"تبدأ جلسة التصوير الجيدة قبل التقاط الصورة الأولى. الهدف هو خلق ظروف تظهر فيها شخصية الحيوان بصورة طبيعية."},{type:"heading",text:"التحضير من دون مبالغة"},{type:"text",text:"يجب أن تبرز العناية جمال الحيوان لا أن تخفيه."},{type:"heading",text:"الإضاءة تغيّر كل شيء"},{type:"text",text:"الإضاءة الطبيعية الناعمة مريحة وجميلة في الصورة."},{type:"quote",text:"أقوى بورتريه يظهر غالباً عندما يتوقف الحيوان عن التصنع ويكون نفسه ببساطة."},{type:"heading",text:"الراحة أولاً"},{type:"text",text:"الماء والمكافآت والاستراحات ضرورية. رفاه الحيوان أهم من الصورة دائماً."}]},
travel:{category:"السفر",title:"صعود السفر الفاخر مع الحيوانات الأليفة",intro:"تعيد الفنادق والوجهات تصميم التجارب الراقية للضيوف الذين يسافرون مع حيواناتهم.",author:"هيئة تحرير PETS & DOGUE",date:"13 أغسطس 2026",readingTime:"5 دقائق للقراءة",body:[{type:"text",text:"السفر الفاخر يتغير. بالنسبة إلى عدد متزايد من الناس، تشمل الضيافة الحقيقية الحيوان أيضاً."},{type:"heading",text:"أكثر من مجرد السماح بالحيوانات"},{type:"text",text:"تفكر أفضل الفنادق في المساحة والوصول إلى الخارج والطعام ومسارات المشي."},{type:"heading",text:"معيار أفضل للضيافة"},{type:"text",text:"الفخامة الحقيقية تعني قواعد واضحة ومساحات آمنة وخدمات تسهّل السفر."},{type:"quote",text:"تنجح الفخامة الصديقة للحيوانات عندما يُعامل الحيوان كضيف."},{type:"heading",text:"السفر مع مراعاة الحيوان"},{type:"text",text:"يجب أن تناسب الرحلة صحته وطباعه وروتينه."}]},
places:{category:"دليل مفيد",title:"كيف يحمي DOGUE Trust توصيات الأماكن الصديقة للحيوانات",intro:"تساعد تقارير المجتمع والتحقق في إبقاء المعلومات موثوقة.",author:"هيئة تحرير PETS & DOGUE",date:"13 أغسطس 2026",readingTime:"4 دقائق للقراءة",body:[{type:"text",text:"قد يصف مكان نفسه بأنه صديق للحيوانات ومع ذلك يقدم تجربة سيئة. القواعد تتغير والمعلومات تصبح قديمة."},{type:"heading",text:"التحقق المجتمعي مهم"},{type:"text",text:"يمكن للزوار الإبلاغ عن تغير القواعد أو الساعات أو القيود."},{type:"heading",text:"DOGUE Trust"},{type:"text",text:"يضيف DOGUE Trust طبقة إضافية من الثقة إلى توصيات المجتمع."},{type:"quote",text:"تنمو الثقة عندما يمكن تصحيح المعلومات الخاطئة."},{type:"heading",text:"دليل حي"},{type:"text",text:"الهدف هو دليل دولي يتطور باستمرار من خلال التجارب الحقيقية."}]},
volunteers:{category:"المجتمع",title:"الأشخاص الذين يساعدون الحيوانات خلف الكواليس",intro:"النقل والاستضافة المؤقتة والتصوير والمهام الصغيرة قد تغيّر فرص الحيوان بالكامل.",author:"هيئة تحرير PETS & DOGUE",date:"13 أغسطس 2026",readingTime:"5 دقائق للقراءة",body:[{type:"text",text:"إنقاذ الحيوانات نادراً ما يكون عمل شخص واحد. خلف قصة التبني قد يوجد سائقون وأسر مؤقتة ومصورون ومتطوعون."},{type:"heading",text:"مهام صغيرة ونتائج كبيرة"},{type:"text",text:"شخص ينقل الحيوان إلى الطبيب، وآخر يلتقط الصور، وثالث يساعد بالطعام."},{type:"heading",text:"الظهور قد ينقذ حياة"},{type:"text",text:"الصور الجيدة والقصص الدقيقة تساعد الشخص المناسب على ملاحظة الحيوان."},{type:"quote",text:"المساعدة لا تحتاج دائماً إلى خطوة كبيرة. الاعتمادية غالباً أكثر قيمة."},{type:"heading",text:"مجتمع أقوى"},{type:"text",text:"عندما يساهم الناس بمهاراتهم ينشأ حول الحيوانات نظام دعم موثوق."}]}
}
